package net.civeira.phylax.features.oauth.authentication.application;

import java.util.List;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.oauth.authentication.domain.AuthRequest;
import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationChallenge;
import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationMode;
import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationResult;
import net.civeira.phylax.features.oauth.client.domain.ClientDetails;
import net.civeira.phylax.features.oauth.user.application.usecase.LoginUsecase;

/**
 * Application service that orchestrates user authentication within an OIDC flow.
 *
 * Responsibilities: - Handle credential-based authentication requests. - Re-validate users after
 * challenge steps.
 *
 * Design notes: - Delegates credential checks to LoginUsecase. - Keeps transport concerns out of
 * the use case.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class AuthenticateUser {

  /**
   * Use case that validates user credentials and pre-authentication state.
   */
  private final LoginUsecase loginUsecase;

  /**
   * Authenticates a user with username and password credentials.
   *
   * This method is used for first-factor login within OIDC flows. It forwards inputs to the login
   * use case without transport details. The returned result encodes success or the required next
   * challenge.
   *
   * @param request the current OIDC auth request context
   * @param challenges challenges already satisfied in this flow (e.g. MFA_DONE)
   * @param username the submitted username
   * @param password the submitted (decrypted) password
   * @param client the OAuth client being used
   * @return the authentication result (right = success, left = failure with exception)
   */
  public AuthenticationResult authenticate(AuthRequest request,
      List<AuthenticationChallenge> challenges, String username, String password,
      ClientDetails client) {
    return loginUsecase.validatedUserData(request, username, password, client, challenges);
  }

  /**
   * Pre-authenticates a user that has already been identified.
   *
   * This is used after challenge steps like MFA or consent. It verifies that the user can proceed
   * for the current client. The method does not perform password validation.
   *
   * @param request the current OIDC auth request context
   * @param challenges challenges already satisfied in this flow
   * @param username the already-identified username
   * @param client the OAuth client being used
   * @return the authentication result
   */
  public AuthenticationResult preAuthenticate(AuthRequest request,
      List<AuthenticationChallenge> challenges, String username, ClientDetails client) {
    AuthenticationMode mode =
        challenges.contains(AuthenticationChallenge.MFA) ? AuthenticationMode.MFA
            : AuthenticationMode.SESSION;
    return loginUsecase.fillPreAuthenticated(request, username, client, challenges, mode);
  }
}
